mapper.update:
UPDATE oc_after_sale
SET status = #{toStatus},
    audit_time = #{auditTime},
    audit_by = #{auditBy},
    audit_remark = #{auditRemark},
    receiver_name = #{receiverName},
    receiver_mobile = #{receiverMobile},
    receiver_address = #{receiverAddress},
    update_time = #{auditTime}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND after_sale_no = #{afterSaleNo}
  AND status = #{fromStatus}

UPDATE oc_after_sale
SET status = #{toStatus},
    return_express_company = #{returnExpressCompany},
    return_express_no = #{returnExpressNo},
    return_time = #{returnTime},
    update_time = #{returnTime}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND after_sale_no = #{afterSaleNo}
  AND status = #{fromStatus}
  AND (return_express_no IS NULL OR return_express_no = '')

UPDATE oc_after_sale
SET status = #{toStatus},
    inspect_time = #{inspectTime},
    inspect_remark = #{inspectRemark},
    update_time = #{inspectTime}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND after_sale_no = #{afterSaleNo}
  AND status = #{fromStatus}

UPDATE oc_after_sale
SET status = #{toStatus},
    refund_time = #{refundTime},
    refund_trade_no = #{refundTradeNo},
    update_time = #{refundTime}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND after_sale_no = #{afterSaleNo}
  AND status = #{fromStatus}

UPDATE oc_after_sale
SET status = #{toStatus},
    update_time = #{updateTime}
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND after_sale_no = #{afterSaleNo}
  AND status = #{fromStatus}
